class Solution {public:long long solve(vector<int> a,vector<int> b){if(a.size()>b.size())swap(a,b);int n=a.size()+b.size(),half=(n+1)/2,l=0,h=a.size();while(l<=h){int i=l+(h-l)/2,j=half-i;long long x=i?a[i-1]:LLONG_MIN,y=i<(int)a.size()?a[i]:LLONG_MAX,u=j?b[j-1]:LLONG_MIN,v=j<(int)b.size()?b[j]:LLONG_MAX;if(x<=v&&u<=y)return n%2?2*max(x,u):max(x,u)+min(y,v);if(x>v)h=i-1;else l=i+1;}return 0;}};